package com.library.stocktake;

import com.fasterxml.jackson.databind.*;
import com.library.stocktake.StocktakeService.Actor;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.library.stocktake.StocktakeSupport.*;

@Service
public class StocktakeResolutionService {
    final StocktakeService stock;
    public StocktakeResolutionService(StocktakeService stock){this.stock=stock;}
    Map<String,Object>row(long id,boolean lock){List<Map<String,Object>>r=stock.jdbc.queryForList("SELECT * FROM stocktake_resolution WHERE id=?"+(lock?" FOR UPDATE NOWAIT":""),id);if(r.isEmpty())throw fail(404,"STOCKTAKE_NOT_FOUND");return r.get(0);}
    JsonNode view(Map<String,Object>r){JsonNode intent=read((String)r.get("intent_json"));List<JsonNode>events=stock.jdbc.queryForList("SELECT * FROM stocktake_resolution_event WHERE resolution_id=? ORDER BY id",r.get("id")).stream().map(e->(JsonNode)obj("eventId",e.get("id"),"kind",e.get("kind"),"actorId",e.get("actor_id"),"occurredAt",time(e.get("occurred_at")),"reason",e.get("reason"),"evidence",read((String)e.get("evidence_json")))).toList();return obj("resolutionId",r.get("id"),"sessionId",r.get("session_id"),"differenceIds",intent.path("differenceIds"),"decision",intent.path("decision"),"workflow",intent.path("workflow"),"candidateId",intent.path("candidateId"),"state",r.get("state"),"version",r.get("version"),"actorId",r.get("actor_id"),"createdAt",time(r.get("created_at")),"reason",intent.path("reason"),"candidate",intent.path("candidate"),"events",events);}
    public JsonNode get(long id,Actor a){a.administrator();return stock.transaction(false,true,()->view(row(id,false)));}
    public JsonNode page(long id,int page,int size,Actor a){a.role();return stock.transaction(false,true,()->{var s=stock.sessionRow(id,false);stock.access(s,a,false);return stock.slice(stock.jdbc.queryForList("SELECT * FROM stocktake_resolution WHERE session_id=? ORDER BY id",id).stream().map(this::view).toList(),page,size);});}
    JsonNode diff(long id){List<Map<String,Object>>r=stock.jdbc.queryForList("SELECT * FROM stocktake_difference WHERE id=?",id);if(r.isEmpty())throw fail(404,"STOCKTAKE_NOT_FOUND");JsonNode d=stock.difference(r.get(0));var s=stock.sessionRow(d.path("sessionId").asLong(),false);if(!"FINALIZED".equals(s.get("state"))||num(s.get("final_snapshot_id"))!=d.path("reviewSnapshotId").asLong())throw fail("RESOLUTION_CONFLICT");return d;}
    record Source(String from,String where,List<Object>args){}
    Source source(JsonNode difference,String workflow){if(!List.of("INTAKE","MOVE","WRITE_OFF","RESTORE","ENABLE").contains(workflow))invalid();if(workflow.equals("INTAKE")){if(!difference.path("type").asText().equals("UNKNOWN_BARCODE")||!difference.path("rawBarcode").isTextual())throw fail("RESOLUTION_CONFLICT");return new Source(" FROM inventory_intake_copy x JOIN inventory_intake_request r ON r.id=x.intake_id JOIN book_copy c ON c.id=x.copy_id "," WHERE r.state='COMMITTED' AND c.barcode_key=?",new ArrayList<>(List.of(bytes(difference.path("rawBarcode").asText()))));}if(!difference.path("copyId").isIntegralNumber())throw fail("RESOLUTION_CONFLICT");return new Source(" FROM book_copy_action x JOIN book_copy_action_request r ON r.id=x.request_id "," WHERE r.state='COMMITTED' AND x.action_type=? AND x.copy_id=?",new ArrayList<>(List.of(workflow,difference.path("copyId").asLong())));}
    String select(String workflow){return workflow.equals("INTAKE")?"SELECT x.id,x.intake_id AS request_id,x.copy_id,x.book_id,c.barcode,x.stock_flow_id,r.confirmed_at AS committed_at":"SELECT x.id,x.request_id,x.copy_id,x.book_id,x.barcode_snapshot AS barcode,x.stock_flow_id,r.committed_at";}
    JsonNode candidate(Map<String,Object>r,String workflow){return obj("workflow",workflow,"candidateId",r.get("id"),"requestId",r.get("request_id"),"copyId",r.get("copy_id"),"bookId",r.get("book_id"),"barcode",r.get("barcode"),"stockFlowId",r.get("stock_flow_id"),"committedAt",time(r.get("committed_at")));}
    public JsonNode candidates(long difference,String workflow,int page,int size,Actor a){a.administrator();return stock.transaction(false,true,()->{JsonNode d=diff(difference);Source s=source(d,workflow);List<Object>args=new ArrayList<>(s.args);long total=stock.jdbc.queryForObject("SELECT COUNT(*)"+s.from+s.where,Long.class,args.toArray());int p=Math.max(1,page),n=Math.max(1,Math.min(100,size));args.add(n);args.add(((long)p-1)*n);return StocktakeService.page(stock.jdbc.queryForList(select(workflow)+s.from+s.where+" ORDER BY x.id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(r->candidate(r,workflow)).toList(),total,p,n);});}
    JsonNode chosen(JsonNode difference,String workflow,long id){Source s=source(difference,workflow);List<Object>args=new ArrayList<>(s.args);args.add(id);List<Map<String,Object>>r=stock.jdbc.queryForList(select(workflow)+s.from+s.where+" AND x.id=?",args.toArray());if(r.size()!=1)throw fail("RESOLUTION_CONFLICT");return candidate(r.get(0),workflow);}
    public JsonNode resolve(JsonNode raw,Actor a){a.administrator();JsonNode valid=validate("RESOLVE",raw);long session=valid.path("sessionId").asLong();return stock.run("RESOLVE",session,valid,a,true,(op,s,in)->{if(!"FINALIZED".equals(s.get("state")))throw fail("RESOLUTION_CONFLICT");JsonNode candidate=null;for(JsonNode id:in.path("differenceIds")){JsonNode d=diff(id.asLong());if(d.path("sessionId").asLong()!=session)throw fail("RESOLUTION_CONFLICT");if(in.path("decision").asText().equals("BUSINESS_REQUIRED")){JsonNode c=chosen(d,in.path("workflow").asText(),in.path("candidateId").asLong());if(candidate!=null&&!candidate.equals(c))throw fail("RESOLUTION_CONFLICT");candidate=c;}}
        String decision=in.path("decision").asText(),state=decision.equals("BUSINESS_REQUIRED")?"AWAITING_LINK":decision.equals("OPEN")?"OPEN":"NO_ACTION";JsonNode intent=obj("differenceIds",in.path("differenceIds"),"decision",decision,"workflow",in.path("workflow"),"candidateId",in.path("candidateId"),"candidate",candidate,"reason",in.path("reason"));long id=insert(stock.jdbc,"INSERT INTO stocktake_resolution(session_id,intent_json,state,version,actor_id,created_at) VALUES (?,?,?,0,?,?)",session,write(intent),state,a.id(),local(now()));event(id,op,decision.equals("BUSINESS_REQUIRED")?"INTENT":"DECIDE",null,intent,a,in.path("reason").asText());return stock.result(null,List.of(),null,null,view(row(id,false)));});}
    void event(long id,long op,String kind,String source,JsonNode evidence,Actor a,String reason){insert(stock.jdbc,"INSERT INTO stocktake_resolution_event(resolution_id,operation_id,kind,source_identity,evidence_json,actor_id,occurred_at,reason) VALUES (?,?,?,?,?,?,?,?)",id,op,kind,bytes(source),write(evidence),a.id(),local(now()),reason);}
    public JsonNode change(long id,JsonNode raw,Actor a,boolean revoke){a.administrator();long session=num(row(id,false).get("session_id"));String operation=revoke?"REVOKE":"LINK";return stock.run(operation,session,raw,a,true,"RESOLUTION:"+id,(op,s,in)->{var r=row(id,true);JsonNode intent=read((String)r.get("intent_json"));long version=num(r.get("version"));if(version==Long.MAX_VALUE||version!=in.path("expectedVersion").asLong()||!(revoke?"LINKED":"AWAITING_LINK").equals(r.get("state")))throw fail("RESOLUTION_CONFLICT");JsonNode candidate=intent.path("candidate");String source=null;if(!revoke){for(JsonNode difference:intent.path("differenceIds"))if(!hash(chosen(diff(difference.asLong()),intent.path("workflow").asText(),intent.path("candidateId").asLong())).equals(hash(candidate)))throw fail("RESOLUTION_CONFLICT");source=intent.path("workflow").asText()+":"+intent.path("candidateId").asLong();if(stock.jdbc.queryForObject("SELECT COUNT(*) FROM stocktake_resolution_event WHERE source_identity=?",Long.class,bytes(source))!=0)throw fail("RESOLUTION_CONFLICT");}event(id,op,operation,source,obj("candidate",candidate,"previousVersion",version),a,in.path("reason").asText());stock.jdbc.update("UPDATE stocktake_resolution SET state=?,version=version+1 WHERE id=? AND version=?",revoke?"REVOKED":"LINKED",id,version);return stock.result(null,List.of(),null,null,view(row(id,false)));});}
    public JsonNode export(long id,long review,Actor a){a.role();return stock.transaction(false,true,()->{var s=stock.sessionRow(id,false);stock.access(s,a,false);JsonNode snapshot=stock.projection.snapshot(id,review);List<JsonNode>diff=stock.jdbc.queryForList("SELECT * FROM stocktake_difference WHERE session_id=? AND review_snapshot_id=? ORDER BY id",id,review).stream().map(stock::difference).toList();List<JsonNode>resolutions=stock.jdbc.queryForList("SELECT * FROM stocktake_resolution WHERE session_id=? ORDER BY id",id).stream().map(this::view).toList();return obj("schemaVersion",1,"session",stock.session(s),"review",snapshot,"differences",diff,"resolutions",resolutions,"asOf",now());});}
    public byte[] csv(JsonNode export){StringBuilder csv=new StringBuilder("\uFEFF");csv.append("schemaVersion,sessionId,snapshotId,completionKind,createdAt,confirmedAt,scopeJson,coverageJson,differenceId,type,copyId,barcode,rawBarcodeBase64,registeredJson,observedJson,resolutionState,asOf\r\n");JsonNode s=export.path("session"),r=export.path("review");for(JsonNode d:export.path("differences")){List<String>states=new ArrayList<>();for(JsonNode x:export.path("resolutions"))for(JsonNode i:x.path("differenceIds"))if(i.equals(d.path("differenceId")))states.add(x.path("state").asText());List<String>cells=Arrays.asList("1",s.path("sessionId").asText(),r.path("snapshotId").asText(),value(r.get("completionKind")),value(r.get("createdAt")),value(s.get("confirmedAt")),write(s.path("scope")),write(r.path("coverage")),d.path("differenceId").asText(),d.path("type").asText(),value(d.get("copyId")),d.path("rawBarcode").isNull()?value(d.path("evidence").path("registered").get("barcode")):value(d.get("rawBarcode")),value(d.get("rawBarcodeBase64")),write(d.path("evidence").path("registered")),write(d.path("evidence").path("observedPlacements")),String.join("|",states),export.path("asOf").asText());for(int i=0;i<cells.size();i++){if(i>0)csv.append(',');String cell=cells.get(i);if(i!=12&&!cell.stripLeading().isEmpty()&&"=+-@".indexOf(cell.stripLeading().charAt(0))>=0)cell="'"+cell;csv.append('"').append(cell.replace("\"","\"\"")).append('"');}csv.append("\r\n");}return csv.toString().getBytes(StandardCharsets.UTF_8);}
    String value(JsonNode n){return n==null||n.isNull()?"":n.asText();}
}
